import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const rootStylePath = join(root, "style.css");
const importsPath = join(root, "styles", "style.css");
const outputPath = join(root, "styles", "bundle.css");

const rootStyle = readFileSync(rootStylePath, "utf8").replace(
    /@import\s+url\(["']\.\/styles\/style\.css["']\);\s*/g,
    ""
);

const imports = readFileSync(importsPath, "utf8")
    .split(/\r?\n/)
    .map((line) => line.match(/@import\s+url\(["']\.\/components\/([^"']+)["']\);/))
    .filter(Boolean)
    .map((match) => match[1]);

const parts = [
    "/* Generated by tools/generate-css-bundle.mjs. Do not edit by hand. */",
    rootStyle.trim()
];

for (const fileName of imports) {
    const filePath = join(root, "styles", "components", fileName);
    const css = readFileSync(filePath, "utf8").replace(
        /url\((["']?)\.\.\/\.\.\/assets\//g,
        "url($1../assets/"
    );

    parts.push(`\n/* ${fileName} */\n${css.trim()}`);
}

writeFileSync(outputPath, `${parts.join("\n\n")}\n`, "utf8");
